package controller;
import model.User;import util.DBConnection;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.util.*;
@WebServlet("/payment-history") public class PaymentHistoryServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{HttpSession h=q.getSession(false);User u=h==null?null:(User)h.getAttribute("user");if(u==null){s.sendRedirect("login.jsp");return;}List<Map<String,Object>> rows=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT p.payment_id,p.booking_id,p.amount,p.payment_date,p.payment_method,p.payment_status,p.transaction_id,b.total_amount FROM payments p JOIN bookings b ON b.booking_id=p.booking_id WHERE b.user_id=? ORDER BY p.payment_date DESC,p.payment_id DESC")){p.setInt(1,u.getUserId());try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();for(String k:new String[]{"payment_id","booking_id","amount","payment_date","payment_method","payment_status","transaction_id","total_amount"})m.put(k,r.getObject(k));rows.add(m);}}}catch(SQLException e){throw new ServletException(e);}q.setAttribute("payments",rows);q.getRequestDispatcher("payment-history.jsp").forward(q,s);}}
